	buffer_cost_of_opening_x[0] = cost_of_opening_x[0];

L9:	float x_cost[BUF_SIZE];
#pragma HLS array_partition variable=x_cost type=auto{_ARRAY_T_L9} factor=auto{_ARRAY_F_L9} dim=auto{_ARRAY_D_L9}

L10:	int buffer_assign_1[BUF_SIZE];
#pragma HLS array_partition variable=buffer_assign_1 type=auto{_ARRAY_T_L10} factor=auto{_ARRAY_F_L10} dim=auto{_ARRAY_D_L10}
L11:	float buffer_cost_1[BUF_SIZE];
#pragma HLS array_partition variable=buffer_cost_1 type=auto{_ARRAY_T_L11} factor=auto{_ARRAY_F_L11} dim=auto{_ARRAY_D_L11}
L12:	float buffer_weight_1[BUF_SIZE];
#pragma HLS array_partition variable=buffer_weight_1 type=auto{_ARRAY_T_L12} factor=auto{_ARRAY_F_L12} dim=auto{_ARRAY_D_L12}
L13:	float buffer_coord_1[BUF_SIZE * DIM];
#pragma HLS array_partition variable=buffer_coord_1 type=auto{_ARRAY_T_L13} factor=auto{_ARRAY_F_L13} dim=auto{_ARRAY_D_L13}

L14:	int buffer_assign_2[BUF_SIZE];
#pragma HLS array_partition variable=buffer_assign_2 type=auto{_ARRAY_T_L14} factor=auto{_ARRAY_F_L14} dim=auto{_ARRAY_D_L14}
L15:	float buffer_cost_2[BUF_SIZE];
#pragma HLS array_partition variable=buffer_cost_2 type=auto{_ARRAY_T_L15} factor=auto{_ARRAY_F_L15} dim=auto{_ARRAY_D_L15}
L16:	float buffer_weight_2[BUF_SIZE];
#pragma HLS array_partition variable=buffer_weight_2 type=auto{_ARRAY_T_L16} factor=auto{_ARRAY_F_L16} dim=auto{_ARRAY_D_L16}
L17:	float buffer_coord_2[BUF_SIZE * DIM];
#pragma HLS array_partition variable=buffer_coord_2 type=auto{_ARRAY_T_L17} factor=auto{_ARRAY_F_L17} dim=auto{_ARRAY_D_L17}
	// float x_cost_2[BUF_SIZE];

	memcpy_wide_bus_read_float(buffer_work_mem, (class ap_uint<LARGE_BUS>*)work_mem, 0, BATCH_SIZE * sizeof(float));
	memcpy_wide_bus_read_char(buffer_switch_membership, (class ap_uint<LARGE_BUS>*)switch_membership, 0, BATCH_SIZE * sizeof(char));

	// memcpy(buffer_work_mem, work_mem, BATCH_SIZE * sizeof(float));
	// memcpy(buffer_switch_membership, switch_membership, BATCH_SIZE * sizeof(float));

	memcpy_wide_bus_read_float(buffer_target, (class ap_uint<LARGE_BUS>*)target, 0, DIM * sizeof(float));
